"use client";

import * as React from "react";
import { useMorph } from "@/lib/cojeev-motion/use-morph";
import {
  DayPicker,
  useDayPicker,
  type PropsBase,
  type Matcher,
  type DayButtonProps,
  type MonthCaptionProps,
  type MonthGridProps,
  type WeekNumberProps,
  type WeekdayProps,
  type WeekNumberHeaderProps,
  type RootProps,
} from "react-day-picker";
import { cva } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { Icon, IconButton } from "@/components/ui/icon";
import { useFlowGroup } from "@/lib/cojeev-motion/use-flow";
import {
  motionTokens,
  useChoreography,
} from "@/lib/cojeev-motion/choreography";
import { assignMotionRef } from "@/lib/cojeev-motion/refs";
export type CalendarMark = "pink" | "blue" | "olive" | "yellow" | "ink";
const MarksContext = React.createContext<Record<string, CalendarMark>>({});
export const calendarVariants = cva("v-cal [display:grid] [gap:14px]");
export type CalendarProps = Omit<
  PropsBase,
  "mode" | "onSelect" | "selected" | "disabled" | "required"
> & {
  mode?: "single";
  selected?: Date;
  defaultSelected?: Date;
  onSelect?: (date: Date | undefined) => void;
  disabled?: Matcher | Matcher[];
  marks?: Record<string, CalendarMark>;
  required?: boolean;
};
export function Calendar(calendarProps: CalendarProps) {
  const {
    className,
    selected,
    defaultSelected,
    onSelect,
    marks = {},
    classNames,
    components,
    mode = "single",
    required = false,
    animate = true,
    style,
    ...props
  } = calendarProps;
  const { quiet } = useChoreography();
  const [internalSelected, setInternalSelected] =
    React.useState(defaultSelected);
  const controlled = Object.prototype.hasOwnProperty.call(
    calendarProps,
    "selected",
  );
  const current = controlled ? selected : internalSelected;
  return (
    <MarksContext.Provider value={marks}>
      <DayPicker
        mode={mode}
        selected={current}
        onSelect={(date) => {
          if (required && !date) return;
          setInternalSelected(date);
          onSelect?.(date);
        }}
        showWeekNumber
        weekStartsOn={1}
        ISOWeek
        showOutsideDays={false}
        hideNavigation
        animate={animate && !quiet}
        data-slot="calendar"
        data-part="root"
        data-cal=""
        className={cn(calendarVariants(), className)}
        style={
          {
            ...style,
            "--v-calendar-duration": `${quiet ? 0 : motionTokens.duration.enter}s`,
            "--v-calendar-ease": `cubic-bezier(${motionTokens.ease.enter.join(",")})`,
          } as React.CSSProperties
        }
        classNames={{
          months: "v-cal__months",
          month: "v-cal__month-wrap",
          month_caption: "v-cal__head",
          month_grid: "v-cal__grid",
          weekday: "v-cal__wd",
          week_number: "v-cal__wk",
          week_number_header: "v-cal__wd -wk",
          day_button: "v-cal__d",
          weeks_before_enter: "v-cal__weeks-before-enter",
          weeks_after_enter: "v-cal__weeks-after-enter",
          weeks_before_exit: "v-cal__weeks-before-exit",
          weeks_after_exit: "v-cal__weeks-after-exit",
          caption_before_enter: "v-cal__caption-enter",
          caption_after_enter: "v-cal__caption-enter",
          caption_before_exit: "v-cal__caption-exit",
          caption_after_exit: "v-cal__caption-exit",
          ...classNames,
        }}
        formatters={{
          formatWeekdayName: (date) =>
            date
              .toLocaleDateString("en", { weekday: "short" })
              .slice(0, 2)
              .toUpperCase(),
          formatWeekNumberHeader: () => "WK",
        }}
        components={{
          Root: CalendarRoot,
          MonthCaption: CalendarCaption,
          DayButton: CalendarDayButton,
          MonthGrid: CalendarGrid,
          WeekNumber: CalendarWeekNumber,
          Weekday: CalendarWeekday,
          WeekNumberHeader: CalendarWeekNumberHeader,
          ...components,
        }}
        {...props}
      />
    </MarksContext.Provider>
  );
}

/** DayPicker retains an aria-hidden DOM snapshot during its finite month exit. */
function CalendarRoot({ rootRef, ...props }: RootProps) {
  const host = React.useRef<HTMLDivElement>(null);
  const ref = React.useCallback(
    (node: HTMLDivElement | null) => {
      host.current = node;
      const release = assignMotionRef(rootRef, node);
      return () => {
        host.current = null;
        release();
      };
    },
    [rootRef],
  );
  React.useLayoutEffect(() => {
    const root = host.current;
    if (!root) return;
    const protectSnapshots = () =>
      root
        .querySelectorAll<HTMLElement>(
          '[data-animated-month][aria-hidden="true"]',
        )
        .forEach((snapshot) => {
          snapshot.inert = true;
          snapshot
            .querySelectorAll("[id]")
            .forEach((element) => element.removeAttribute("id"));
        });
    const observer = new MutationObserver(protectSnapshots);
    observer.observe(root, { childList: true, subtree: true });
    protectSnapshots();
    return () => observer.disconnect();
  }, []);
  return <div ref={ref} {...props} />;
}
export function CalendarCaption({
  calendarMonth,
  displayIndex,
  className,
  ...props
}: MonthCaptionProps) {
  const { goToMonth, previousMonth, nextMonth } = useDayPicker();
  const month = calendarMonth.date;
  return (
    <div
      data-slot="calendar-header"
      data-month-index={displayIndex}
      data-part="header"
      className={cn("v-cal__head", className)}
      {...props}
    >
      <span
        data-slot="calendar-caption"
        className="v-cal__month"
        aria-live="polite"
      >
        <b>{month.toLocaleDateString("en", { month: "long" })}</b>
        <span>{month.getFullYear()}</span>
      </span>
      <span data-slot="calendar-nav" className="v-cal__nav">
        <IconButton
          data-slot="calendar-previous"
          data-part="trigger"
          size="sm"
          aria-label="Previous month"
          disabled={!previousMonth}
          onClick={() => previousMonth && goToMonth(previousMonth)}
        >
          <Icon name="chevron-left" />
        </IconButton>
        <IconButton
          data-slot="calendar-next"
          data-part="trigger"
          size="sm"
          aria-label="Next month"
          disabled={!nextMonth}
          onClick={() => nextMonth && goToMonth(nextMonth)}
        >
          <Icon name="chevron-right" />
        </IconButton>
      </span>
    </div>
  );
}
export function CalendarGrid({ className, ...props }: MonthGridProps) {
  const flowRef = useFlowGroup<HTMLTableElement>(undefined, {
    itemSelector: ".v-cal__d",
    activeSelector: '[data-state="active"]',
  });
  return (
    <table
      ref={flowRef}
      data-slot="calendar-grid"
      data-part="viewport"
      className={cn("v-cal__grid", className)}
      {...props}
    />
  );
}
export function CalendarDayButton({
  day,
  modifiers,
  className,
  children,
  ...props
}: DayButtonProps) {
  const marks = React.useContext(MarksContext);
  const ref = React.useRef<HTMLButtonElement>(null);
  const morphRef = useMorph<HTMLButtonElement>("nav", ref);
  React.useEffect(() => {
    if (modifiers.focused) ref.current?.focus();
  }, [modifiers.focused]);
  const date = day.date;
  const iso = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
  const mark = marks[iso];
  return (
    <button
      ref={morphRef}
      data-slot="calendar-day"
      data-part="item"
      data-d={date.getDate()}
      data-today={modifiers.today || undefined}
      data-range-start={modifiers.range_start || undefined}
      data-range-middle={modifiers.range_middle || undefined}
      data-range-end={modifiers.range_end || undefined}
      data-state={modifiers.selected ? "active" : "inactive"}
      aria-pressed={modifiers.selected || undefined}
      className={cn(
        "v-cal__d",
        (date.getDay() === 0 || date.getDay() === 6) && "-off",
        modifiers.today && "-today",
        className,
      )}
      {...props}
    >
      <span>{children}</span>
      {mark && (
        <i
          data-slot="calendar-mark"
          className={`v-cal__mark -${mark}`}
          aria-label="Marked day"
        />
      )}
    </button>
  );
}
export function CalendarWeekNumber({
  week,
  className,
  ...props
}: WeekNumberProps) {
  const { isSelected } = useDayPicker();
  const active = week.days.some((day) => isSelected?.(day.date));
  const weekRef = useMorph<HTMLTableCellElement>("pills");
  return (
    <th
      ref={weekRef}
      data-slot="calendar-week-number"
      className={cn("v-cal__wk", active && "-on", className)}
      {...props}
    />
  );
}

function CalendarWeekday(props: WeekdayProps) {
  return <th data-slot="calendar-weekday" {...props} />;
}

function CalendarWeekNumberHeader(props: WeekNumberHeaderProps) {
  return <th data-slot="calendar-week-number-header" {...props} />;
}

@layer cojeev-states {
/* An open date grid: type carries the hierarchy; colour carries the date state. */
[data-slot="calendar"] { min-width:0; max-width:100%; color:var(--v-text); }
[data-slot="calendar"] .v-cal__months { display:flex; flex-wrap:wrap; gap:28px; min-width:0; max-width:100%; }
[data-slot="calendar"] .v-cal__month-wrap { display:grid; gap:20px; flex:0 1 360px; width:100%; min-width:0; max-width:360px; }
[data-slot="calendar-header"] { display:flex; align-items:center; justify-content:space-between; gap:16px; min-height:44px; }
[data-slot="calendar-caption"] { display:grid; gap:1px; font-family:var(--font-display); background:transparent; color:var(--v-text); }
[data-slot="calendar-caption"] b { font-size:26px; font-weight:600; line-height:1.1; letter-spacing:-.025em; }
[data-slot="calendar-caption"] > span { font-family:var(--font-text); font-size:13px; font-weight:500; line-height:1.5; color:var(--v-text-2); }
[data-slot="calendar-nav"] { display:inline-flex; gap:6px; }
[data-slot="calendar-nav"] .v-ibtn { width:36px; height:36px; color:var(--v-text); background:var(--v-beige); box-shadow:none; }
[data-slot="calendar-nav"] .v-ibtn:not(:disabled):hover { background:var(--v-blue); color:var(--v-on-accent); }
[data-slot="calendar-nav"] .v-icon { width:17px; height:17px; }
[data-slot="calendar-grid"] { display:grid; grid-template-columns:repeat(7,minmax(0,1fr)); align-items:center; justify-items:center; gap:5px 2px; width:100%; border-collapse:collapse; }
[data-slot="calendar-grid"]:has(.v-cal__wk) { grid-template-columns:24px repeat(7,minmax(0,1fr)); }
[data-slot="calendar-grid"] :is(thead,tbody,tr) { display:contents; }
[data-slot="calendar-grid"] td { display:grid; place-items:center; position:relative; width:100%; min-width:0; height:42px; padding:0; }
[data-slot="calendar-weekday"], [data-slot="calendar-week-number-header"] { display:grid; place-items:center; width:100%; height:28px; padding:0; font-size:11px; font-weight:600; color:var(--v-text-2); background:transparent; text-align:center; }
[data-slot="calendar-week-number-header"] { font-size:9px; letter-spacing:.02em; }
[data-slot="calendar-week-number"] { display:grid; place-items:center; width:20px; height:26px; font-size:10px; font-weight:400; color:var(--v-text-2); padding:0; background:transparent; }
[data-slot="calendar-week-number"].-on { color:var(--v-text); font-weight:600; }
[data-slot="calendar-day"] { position:relative; isolation:isolate; display:grid; place-items:center; width:40px; max-width:100%; height:40px; margin:0; padding:0; border:0; border-radius:43% 57% 48% 52% / 55% 44% 56% 45%; background:transparent; color:var(--v-text); font-size:14px; font-weight:500; font-variant-numeric:tabular-nums; cursor:pointer; }
[data-slot="calendar-day"] > span { position:relative; z-index:1; }
[data-slot="calendar-day"]:not(:disabled):not([aria-pressed="true"]):hover { background:var(--v-beige); }
[data-slot="calendar-day"][aria-pressed="true"] { background:var(--v-pink); color:var(--v-on-accent); font-weight:700; }
[data-slot="calendar-day"][data-today]:not([aria-pressed="true"]) { box-shadow:inset 0 0 0 1.5px var(--v-blue); font-weight:700; }
[data-slot="calendar-day"][data-today]::after { content:""; position:absolute; width:3px; height:3px; bottom:4px; border-radius:50%; background:currentColor; }
[data-slot="calendar-day"][data-range-middle] { border-radius:4px; background:color-mix(in oklab,var(--v-pink) 20%,var(--v-canvas)); }
[data-slot="calendar-day"]:is([data-range-start],[data-range-end]) { background:var(--v-pink); color:var(--v-on-accent); }
[data-slot="calendar-day"]:disabled { color:var(--v-disabled-ink); cursor:not-allowed; }
[data-slot="calendar-day"]:focus-visible { outline:2px solid var(--ring); outline-offset:2px; }
[data-slot="calendar-mark"] { position:absolute; bottom:4px; width:4px; height:4px; border-radius:50%; background:var(--v-pink-deep); z-index:1; }
[data-slot="calendar-mark"].-blue { background:var(--v-blue-deep); }
[data-slot="calendar-mark"].-olive { background:var(--v-olive); }
[data-slot="calendar-mark"].-yellow { background:var(--v-yellow-deep); }
[data-slot="calendar-mark"].-ink { background:var(--v-text); }
[data-slot="calendar-day"][aria-pressed="true"] [data-slot="calendar-mark"] { background:var(--v-on-accent); }
@media(max-width:420px) { [data-slot="calendar-day"] { width:36px; height:38px; font-size:13px; } [data-slot="calendar-grid"] td { height:40px; } [data-slot="calendar"] .v-cal__month-wrap { gap:16px; } }
@media(prefers-reduced-motion:reduce) { [data-slot="calendar"] *, [data-slot="calendar"] *::before, [data-slot="calendar"] *::after { animation-duration:0s; transition-duration:0s; } }

/* DayPicker owns retained month snapshots; shared timing keeps both sides finite. */
.v-cal [data-animated-weeks] { display:grid; grid-column:1 / -1; grid-template-columns:inherit; gap:inherit; align-items:inherit; justify-items:inherit; }
.v-cal .v-cal__caption-enter { animation:v-cal-caption-in var(--v-calendar-duration) var(--v-calendar-ease) both; }
.v-cal .v-cal__caption-exit { animation:v-cal-caption-out var(--v-calendar-duration) var(--v-calendar-ease) both; }
.v-cal .v-cal__weeks-after-enter,
.v-cal:dir(rtl) .v-cal__weeks-before-enter { animation:v-cal-month-in-right var(--v-calendar-duration) var(--v-calendar-ease) both; }
.v-cal .v-cal__weeks-before-enter,
.v-cal:dir(rtl) .v-cal__weeks-after-enter { animation:v-cal-month-in-left var(--v-calendar-duration) var(--v-calendar-ease) both; }
.v-cal .v-cal__weeks-before-exit,
.v-cal:dir(rtl) .v-cal__weeks-after-exit { animation:v-cal-month-out-left var(--v-calendar-duration) var(--v-calendar-ease) both; }
.v-cal .v-cal__weeks-after-exit,
.v-cal:dir(rtl) .v-cal__weeks-before-exit { animation:v-cal-month-out-right var(--v-calendar-duration) var(--v-calendar-ease) both; }
.v-cal [data-animated-month][aria-hidden="true"] { width:100%; inset:0 auto auto 0; }
@keyframes v-cal-caption-in { from { opacity:0; } to { opacity:1; } }
@keyframes v-cal-caption-out { from { opacity:1; } to { opacity:0; } }
@keyframes v-cal-month-in-right { from { opacity:0; transform:translateX(12px); } to { opacity:1; transform:translateX(0); } }
@keyframes v-cal-month-in-left { from { opacity:0; transform:translateX(-12px); } to { opacity:1; transform:translateX(0); } }
@keyframes v-cal-month-out-left { from { opacity:1; transform:translateX(0); } to { opacity:0; transform:translateX(-12px); } }
@keyframes v-cal-month-out-right { from { opacity:1; transform:translateX(0); } to { opacity:0; transform:translateX(12px); } }

}
